WITH with_latest AS (SELECT s.*, top1.web_event_event_time, top1.page FROM sessions s LEFT JOIN LATERAL (SELECT c.event_time AS web_event_event_time, c.page FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, customer_id, device, browser, started_at, page, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS device_zone FROM with_latest ORDER BY id NULLS FIRST
